const fs = require('fs');

function main() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readNextString() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        const start = offset;
        while (offset < buffer.length && buffer[offset] > 32) {
            offset++;
        }
        return buffer.toString('ascii', start, offset);
    }

    const firstToken = readNextString();
    if (!firstToken) return;

    const N = parseInt(firstToken, 10);
    const F = parseInt(readNextString(), 10);

    const grid = new Array(N);
    for (let i = 0; i < N; i++) {
        // We can work directly with Buffer subarrays for speed and memory efficiency
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        const start = offset;
        while (offset < buffer.length && buffer[offset] > 32) {
            offset++;
        }
        grid[i] = buffer.subarray(start, offset);
    }

    // Fissure starts at (0, 0)
    const STAR = 42; // ASCII code for '*'
    const fCode = 48 + F; // ASCII code for '0' + F

    if (grid[0][0] <= fCode) {
        // BFS using an Int32Array queue
        const queueR = new Int32Array(N * N);
        const queueC = new Int32Array(N * N);
        let head = 0;
        let tail = 0;

        grid[0][0] = STAR;
        queueR[tail] = 0;
        queueC[tail] = 0;
        tail++;

        const dr = [-1, 1, 0, 0];
        const dc = [0, 0, -1, 1];

        while (head < tail) {
            const r = queueR[head];
            const c = queueC[head];
            head++;

            for (let i = 0; i < 4; i++) {
                const nr = r + dr[i];
                const nc = c + dc[i];

                if (nr >= 0 && nr < N && nc >= 0 && nc < N) {
                    const val = grid[nr][nc];
                    if (val !== STAR && val <= fCode) {
                        grid[nr][nc] = STAR;
                        queueR[tail] = nr;
                        queueC[tail] = nc;
                        tail++;
                    }
                }
            }
        }
    }

    // Output result
    const out = [];
    for (let i = 0; i < N; i++) {
        out.push(grid[i].toString('ascii'));
    }
    process.stdout.write(out.join('\n') + '\n');
}

main();
